import java.io.*;
import java.util.*;

// A custom ObjectInputStream that implements a whitelist (Look-ahead deserialization)
class ValidatedObjectInputStream extends ObjectInputStream {
    private final Set<String> allowedClasses;

    public ValidatedObjectInputStream(InputStream in, Set<String> allowedClasses) throws IOException {
        super(in);
        this.allowedClasses = allowedClasses;
    }

    @Override
    protected Object readClassDescriptor() throws IOException, ClassNotFoundException {
        // Resolve the class name before allowing instantiation
        Object desc = super.readClassDescriptor();
        String className = desc.getClassDescriptor().getName();

        // Check if the class is in our safe whitelist
        if (!allowedClasses.contains(className)) {
            throw new InvalidClassException("Unauthorized deserialization attempt: " + className);
        }
        return desc;
    }
}

public class SecureDeserialization {

    public void safeDeserialize(InputStream inputStream) throws Exception {
        // Define a strict whitelist of classes allowed to be deserialized
        Set<String> whitelist = new HashSet<>(Arrays.asList("java.lang.String", "java.util.ArrayList"));

        // Use the validated stream instead of the standard ObjectInputStream
        try (ValidatedObjectInputStream vois = new ValidatedObjectInputStream(inputStream, whitelist)) {
            Object obj = vois.readObject();
            System.out.println("Deserialized object: " + obj.toString());
        } catch (InvalidClassException e) {
            System.err.println("Security Alert: Blocked unauthorized class!");
        }
    }

    public static void main(String[] args) throws Exception {
        byte[] data = { /* payload bytes */ };
        SecureDeserialization demo = new SecureDeserialization();
        demo.safeDeserialize(new ByteArrayInputStream(data));
    }
}
```

